//! Plans one `child!`: the Rust bindings and the
//! manifest for one guest component (a *child*) plugged into a donut.
//!
//! Given the guest's world `G` and the child's name, every interface `G`
//! imports is **virtualized** unless it matches `import_passthrough`, and
//! every interface `G` exports can be called from Rust. This produces, all
//! inside `pub mod <name>`:
//!
//! * **One world**, generated by one wit-bindgen run:
//!   * it *exports* a renamed copy (`virtual-<child>:<ns>-<pkg>`) of each
//!     virtualized interface;
//!   * it *imports* a renamed copy (`guest-<child>:<ns>-<pkg>`) of each of
//!     the guest's exports, so that calls into this child have core import
//!     names of their own (`"guest-a:ns-pkg/iface" "f"`), plus types-only
//!     copies of the virtualized interfaces those use. Their resources are
//!     import-side resources of their own, which `with` maps to the virtual
//!     copies' Rust types, so the world's imports never mention its exports'
//!     types;
//!   * and it imports the host interfaces either side uses.
//!
//!   Its `component-type` section merges with the donut's own world; the
//!   encoder then drops the `guest-<child>` imports, which are the child's
//!   exports, not the host's. The manifest lists them all.
//! * **`virt`** and **`guest`**: re-exports of the copies under their
//!   original paths, so users implement `<name>::virt::<ns>::<pkg>::<iface>`
//!   and call `<name>::guest::…`.
//! * The `wit-bindgen-child:<name>` manifest section.

mod copy;
mod manifest;
mod pattern;

pub use copy::{GUEST, VIRTUAL, copy_package_name};
pub use manifest::{Manifest, SECTION_PREFIX, VERSION as MANIFEST_VERSION};
pub use pattern::Pattern;

use anyhow::{Context, Result, bail};
use heck::ToUpperCamelCase;
use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write;
use wit_bindgen_core::{Files, WorldGenerator, name_package_module};
use wit_bindgen_rust::{Opts, WithOption, to_rust_ident};
use wit_parser::{
    FunctionKind, Handle, InterfaceId, LiveTypes, PackageId, Resolve, Type, TypeDefKind, TypeId, TypeOwner,
    WorldId, WorldItem, WorldKey,
};

/// One `child!` invocation.
#[derive(Clone, Debug, Default)]
pub struct Config {
    /// The child's name, in snake case: the generated module. Its kebab-case
    /// form is the hole's import name.
    pub name: String,
    /// The guest's world `G`, e.g. `example:app/app`.
    pub guest: String,
    /// Guest imports passed straight through from the donut's host
    /// ([`Pattern`]s). Every other guest import is virtualized.
    pub import_passthrough: Vec<String>,
    /// Guest exports the donut re-exports unchanged ([`Pattern`]s).
    pub export_passthrough: Vec<String>,
    /// wit-bindgen options for the child's bindings (`with`,
    /// `additional_derive_attributes`, …). `generate_all` and
    /// `default_bindings_module` are always set.
    pub opts: Opts,
}

/// A child's name.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Name {
    /// `my_app`: the Rust module.
    pub snake: String,
    /// `my-app`: the hole's import name, and part of generated WIT names.
    pub kebab: String,
}

impl Name {
    /// Snake-case words that each start with a letter, so that the kebab
    /// form is a valid component name and the conversion is lossless.
    pub fn parse(s: &str) -> Result<Name> {
        let words_ok = !s.is_empty()
            && s.split('_').all(|w| {
                w.chars().next().is_some_and(|c| c.is_ascii_lowercase())
                    && w.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
            });
        if !words_ok {
            bail!(
                "invalid child name `{s}`: use snake_case words that each start with a \
                 letter, like `my_app`, so that it converts to a component name (`my-app`)"
            );
        }
        if to_rust_ident(s) != s {
            bail!("invalid child name `{s}`: it's a Rust keyword");
        }
        Ok(Name { snake: s.to_string(), kebab: s.replace('_', "-") })
    }
}

/// The planned worlds, before generation.
#[derive(Debug)]
pub struct Plan {
    /// The `Resolve`, with the copies and the child's world added.
    pub resolve: Resolve,
    pub name: Name,
    /// `G`.
    pub guest: WorldId,
    /// The child's world: the virtual copies (exported), the guest-side
    /// copies (imported), and the host interfaces they use (imported).
    pub world: WorldId,
    /// Virtualized guest imports.
    pub virtualized: Vec<InterfaceId>,
    /// For each of `virtualized`, its copy, which the world exports.
    pub virtual_exports: Vec<InterfaceId>,
    /// Passthrough guest imports.
    pub passthrough: Vec<InterfaceId>,
    /// The guest's exported interfaces.
    pub guest_exports: Vec<InterfaceId>,
    /// For each of `guest_exports`, its copy, which the world imports.
    pub guest_export_copies: Vec<InterfaceId>,
    /// Virtualized interfaces the guest's exports use.
    pub guest_deps: Vec<InterfaceId>,
    /// For each of `guest_deps`, its types-only guest-side copy.
    pub guest_dep_copies: Vec<InterfaceId>,
    /// The guest exports the donut re-exports.
    pub export_passthrough: Vec<InterfaceId>,
    pub opts: Opts,
}

/// Generated Rust source, and the manifest it embeds.
pub struct Output {
    pub source: String,
    pub manifest: Manifest,
}

impl Plan {
    /// Classifies `G`'s imports and exports, checks them, and builds the
    /// child's world in a copy of `resolve`.
    pub fn new(resolve: &Resolve, packages: &[PackageId], config: &Config) -> Result<Plan> {
        let name = Name::parse(&config.name)?;
        let mut resolve = resolve.clone();
        let guest = resolve
            .select_world(packages, Some(&config.guest))
            .with_context(|| format!("selecting the guest world `{}`", config.guest))?;
        reject_unsupported(&resolve, guest)?;
        let import_patterns = parse_patterns(&config.import_passthrough)?;
        let export_patterns = parse_patterns(&config.export_passthrough)?;
        let g = &resolve.worlds[guest];

        // 1. Classify: every import is virtualized unless passed through.
        let mut used = vec![false; import_patterns.len()];
        let mut virtualized = Vec::new();
        let mut passthrough = Vec::new();
        for (key, item) in g.imports.iter() {
            let item_name = resolve.name_world_key(key);
            match (key, item) {
                (WorldKey::Interface(_), WorldItem::Interface { id, .. }) => {
                    if matches_any(&resolve, *id, &import_patterns, &mut used) {
                        passthrough.push(*id);
                    } else {
                        virtualized.push(*id);
                    }
                }
                (WorldKey::Name(_), WorldItem::Interface { .. }) => {
                    bail!("guest import `{item_name}` is an inline interface, which isn't supported yet")
                }
                (_, WorldItem::Function(_)) => {
                    bail!("guest import `{item_name}` is a world-level function, which isn't supported yet")
                }
                (_, WorldItem::Type { .. }) => {}
            }
        }
        unused_patterns(&import_patterns, &used, "import_passthrough", "imported", &config.guest)?;

        let mut used = vec![false; export_patterns.len()];
        let mut guest_exports = Vec::new();
        let mut export_passthrough = Vec::new();
        for (key, item) in g.exports.iter() {
            let item_name = resolve.name_world_key(key);
            match (key, item) {
                (WorldKey::Interface(_), WorldItem::Interface { id, .. }) => {
                    guest_exports.push(*id);
                    if matches_any(&resolve, *id, &export_patterns, &mut used) {
                        export_passthrough.push(*id);
                    }
                }
                (WorldKey::Name(_), WorldItem::Interface { .. }) => {
                    bail!("guest export `{item_name}` is an inline interface, which isn't supported yet")
                }
                _ => bail!("guest export `{item_name}` is a world-level item, which isn't supported yet"),
            }
        }
        unused_patterns(&export_patterns, &used, "export_passthrough", "exported", &config.guest)?;

        // 2. A passthrough import can't mention a virtual resource: the
        // host's `send(request)` can't take the child's virtual `request`.
        let virtual_set = virtualized.iter().copied().collect::<BTreeSet<_>>();
        for p in passthrough.iter() {
            for (r, owner) in resources_used(&resolve, *p) {
                if virtual_set.contains(&owner) {
                    bail!(
                        "`{p}` is passed through, but it uses resource `{r}` of `{o}`, which is \
                         virtualized: the host's `{p}` can't take the child's virtual `{r}`. \
                         Add `{o}` to `import_passthrough` too",
                        p = resolve.id_of(*p).unwrap(),
                        r = resource_name(&resolve, r),
                        o = resolve.id_of(owner).unwrap(),
                    );
                }
            }
        }

        // 3. A re-exported interface can only mention host resources
        // (passthrough imports) and resources of re-exported interfaces: a
        // virtual resource has no name outside the donut.
        let export_set = guest_exports.iter().copied().collect::<BTreeSet<_>>();
        let reexport_set = export_passthrough.iter().copied().collect::<BTreeSet<_>>();
        for e_id in export_passthrough.iter() {
            for (r, owner) in resources_used(&resolve, *e_id) {
                // Its own resources are the guest's.
                if owner == *e_id {
                    continue;
                }
                let (e, r, o) = (resolve.id_of(*e_id).unwrap(), resource_name(&resolve, r), resolve.id_of(owner).unwrap());
                if export_set.contains(&owner) {
                    if !reexport_set.contains(&owner) {
                        bail!(
                            "`{e}` is re-exported, but it uses resource `{r}` of `{o}`, which \
                             isn't: add `{o}` to `export_passthrough` too"
                        );
                    }
                } else if virtual_set.contains(&owner) {
                    bail!(
                        "`{e}` is re-exported, but it uses resource `{r}` of `{o}`, which is \
                         virtualized and has no name outside the donut: add `{o}` to \
                         `import_passthrough`, or don't re-export `{e}`"
                    );
                }
            }
        }

        // 4. Copies: the virtualized interfaces, to export, in
        // `virtual-<child>:<ns>-<pkg>`; the guest's exports, to import, in
        // `guest-<child>:<ns>-<pkg>`, together with types-only copies of the
        // virtualized interfaces they use (transitively). Those copies'
        // resources are import-side resources of their own, mapped to the
        // virtual copies' Rust types with `with`. The world's imports then
        // never mention its exports' types: neither WIT, nor the component
        // model, nor wit-bindgen (which renders a `borrow` of an exported
        // resource as an inbound `RBorrow`, whichever way the call goes)
        // would allow that.
        let mut used_by_exports = BTreeSet::new();
        let mut stack = guest_exports.clone();
        let mut seen = BTreeSet::new();
        while let Some(id) = stack.pop() {
            if !seen.insert(id) {
                continue;
            }
            for dep in resolve.interface_direct_deps(id) {
                // A passthrough interface only uses passthrough resources (2).
                if virtual_set.contains(&dep) || export_set.contains(&dep) {
                    used_by_exports.insert(dep);
                    stack.push(dep);
                }
            }
        }
        let guest_deps = virtualized
            .iter()
            .copied()
            .filter(|id| used_by_exports.contains(id) && !export_set.contains(id))
            .collect::<Vec<_>>();
        for prefix in [copy::VIRTUAL, copy::GUEST] {
            let ns = format!("{prefix}-{}", name.kebab);
            if let Some((_, pkg)) = resolve.packages.iter().find(|(_, p)| p.name.namespace == ns) {
                bail!("package `{}` clashes with child `{}`'s copies, in namespace `{ns}`", pkg.name, name.snake);
            }
        }
        let guest_side = guest_exports.iter().chain(guest_deps.iter()).copied().collect::<Vec<_>>();
        check_copies(&resolve, copy::VIRTUAL, &name.kebab, &virtualized)?;
        check_copies(&resolve, copy::GUEST, &name.kebab, &guest_side)?;
        let copies = copy::copy_interfaces(&mut resolve, copy::VIRTUAL, &name.kebab, &virtualized);
        let virtual_exports = virtualized.iter().map(|id| copies[id]).collect::<Vec<_>>();
        let copies = copy::copy_interfaces(&mut resolve, copy::GUEST, &name.kebab, &guest_side);
        let guest_export_copies = guest_exports.iter().map(|id| copies[id]).collect::<Vec<_>>();
        let guest_dep_copies = guest_deps.iter().map(|id| copies[id]).collect::<Vec<_>>();
        for id in guest_dep_copies.iter() {
            resolve.interfaces[*id].functions.clear();
        }

        // 5. The child's world. Written as WIT, so that wit-parser adds the
        // dependencies: the guest-side types-only copies, and the host
        // interfaces either side uses. The rest of `G`'s passthrough imports
        // are the encoder's business: it takes them from `G` in the manifest.
        let mut wit = format!("package donut-child:{};\n\nworld child {{\n", name.kebab);
        for id in guest_export_copies.iter() {
            writeln!(wit, "  import {};", resolve.id_of(*id).unwrap())?;
        }
        for id in virtual_exports.iter() {
            writeln!(wit, "  export {};", resolve.id_of(*id).unwrap())?;
        }
        writeln!(wit, "}}")?;
        let pkg = resolve
            .push_source("<child-generated>.wit", &wit)
            .with_context(|| format!("building the child's world:\n{wit}"))?;
        let world = resolve.select_world(&[pkg], Some("child"))?;

        // `virt` and `guest` sit next to the bindings' top-level modules.
        for item in resolve.worlds[world].imports.values() {
            if let WorldItem::Interface { id, .. } = item {
                let ns = &resolve.packages[resolve.interfaces[*id].package.unwrap()].name.namespace;
                if ["virt", "guest"].contains(&to_rust_ident(ns).as_str()) {
                    bail!(
                        "`{}`'s namespace `{ns}` would clash with the generated `{}::{ns}` module",
                        resolve.id_of(*id).unwrap(),
                        name.snake
                    );
                }
            }
        }

        Ok(Plan {
            resolve,
            name,
            guest,
            world,
            virtualized,
            virtual_exports,
            passthrough,
            guest_exports,
            guest_export_copies,
            guest_deps,
            guest_dep_copies,
            export_passthrough,
            opts: config.opts.clone(),
        })
    }

    /// Generates `pub mod <name> { bindings, virt, guest, manifest }`.
    pub fn generate(&self) -> Result<Output> {
        let bindings = self.generate_bindings()?;
        let manifest = self.manifest()?;
        let bytes = manifest.encode();
        let Name { snake, .. } = &self.name;
        let guest = self.resolve.id_of_name(
            self.resolve.worlds[self.guest].package.unwrap(),
            &self.resolve.worlds[self.guest].name,
        );

        let mut source = String::new();
        writeln!(
            source,
            "/// Bindings for child `{snake}`, a guest of world `{guest}` plugged into this \
             component.\n\
             #[allow(dead_code, clippy::all)]\n\
             pub mod {snake} {{\n{bindings}"
        )?;
        source.push_str(&self.alias_module(
            "virt",
            &format!("The interfaces child `{snake}` imports and this component implements:\n/// implement their `Guest` traits."),
            "super::super::exports",
            self.virtualized.iter().zip(self.virtual_exports.iter()),
        ));
        source.push_str(&self.alias_module(
            "guest",
            &format!("Calls into child `{snake}`'s exports."),
            "super::super",
            self.guest_exports.iter().zip(self.guest_export_copies.iter()),
        ));
        writeln!(
            source,
            "#[cfg(target_arch = \"wasm32\")]\n\
             #[unsafe(link_section = \"{section}\")]\n\
             #[used]\n\
             #[doc(hidden)]\n\
             static __CHILD_MANIFEST: [u8; {len}] = {bytes:?};\n}}",
            section = manifest.section_name(),
            len = bytes.len(),
        )?;
        Ok(Output { source, manifest })
    }

    /// The child's manifest.
    pub fn manifest(&self) -> Result<Manifest> {
        let id_of = |id: &InterfaceId| self.resolve.id_of(*id).unwrap();
        let pairs = |a: &[InterfaceId], b: &[InterfaceId]| a.iter().zip(b.iter()).map(|(a, b)| (id_of(a), id_of(b))).collect();
        Manifest::new(
            &self.resolve,
            self.guest,
            &self.name.kebab,
            pairs(&self.virtualized, &self.virtual_exports),
            pairs(&self.guest_exports, &self.guest_export_copies),
            self.guest_dep_copies.iter().map(id_of).collect(),
            self.export_passthrough.iter().map(id_of).collect(),
        )
    }

    fn generate_bindings(&self) -> Result<String> {
        let mut opts = self.opts.clone();
        opts.generate_all = true;
        opts.default_bindings_module = Some(format!("crate::{}", self.name.snake));
        opts.with.extend(self.guest_side_remaps().into_iter().map(|(k, v)| (k, WithOption::Path(v))));
        run(opts, &self.resolve, self.world).context("generating bindings for the child")
    }

    /// The `with` remaps that join the guest-side types-only copies to the
    /// virtual copies: every resource, and every other type whose Rust
    /// rendering is the same on the export side (as a virtual interface's
    /// argument) and the import side (as an argument to the child's export).
    /// That's any type without a `borrow` of a virtual resource: the export
    /// side renders it as an inbound `RBorrow<'a>`, the import side as an
    /// outbound `&R`. Owned virtual resources render the same once remapped.
    /// `use`d aliases aren't remapped: they follow what they alias.
    pub fn guest_side_remaps(&self) -> Vec<(String, String)> {
        let resolve = &self.resolve;
        let dep_copies = self.guest_dep_copies.iter().copied().collect::<BTreeSet<_>>();
        let virtual_resource = |r: TypeId| {
            matches!(resolve.types[dealias(resolve, r)].owner, TypeOwner::Interface(i) if dep_copies.contains(&i))
        };
        let virtual_copy = self.virtualized.iter().zip(self.virtual_exports.iter()).collect::<BTreeMap<_, _>>();
        let mut out = Vec::new();
        for (dep, copy) in self.guest_deps.iter().zip(self.guest_dep_copies.iter()) {
            let target = module_path(resolve, *virtual_copy[dep], true);
            for (name, ty) in resolve.interfaces[*copy].types.iter() {
                let remap = match &resolve.types[*ty].kind {
                    TypeDefKind::Resource => true,
                    TypeDefKind::Type(Type::Id(_)) => false,
                    _ => !type_has(resolve, &Type::Id(*ty), &|h| matches!(h, Handle::Borrow(r) if virtual_resource(*r))),
                };
                if remap {
                    out.push((
                        format!("{}/{name}", resolve.id_of(*copy).unwrap()),
                        format!("crate::{}::{target}::{}", self.name.snake, camel(name)),
                    ));
                }
            }
        }
        out
    }

    /// `pub mod <module>`: copies (from `pairs`, original → copy), under
    /// their original package paths, re-exported from `<raw>` (where
    /// wit-bindgen generated them, relative to `<module>::<ns>`).
    fn alias_module<'a>(
        &self,
        module: &str,
        doc: &str,
        raw: &str,
        pairs: impl Iterator<Item = (&'a InterfaceId, &'a InterfaceId)>,
    ) -> String {
        // namespace module → original package module → the copy's path
        let mut namespaces = BTreeMap::<String, BTreeMap<String, String>>::new();
        for (id, copy) in pairs {
            let pkg = self.resolve.interfaces[*id].package.unwrap();
            let copy_pkg = self.resolve.interfaces[*copy].package.unwrap();
            let copy_path = format!(
                "{}::{}",
                to_rust_ident(&self.resolve.packages[copy_pkg].name.namespace),
                name_package_module(&self.resolve, copy_pkg)
            );
            namespaces
                .entry(to_rust_ident(&self.resolve.packages[pkg].name.namespace))
                .or_default()
                .insert(name_package_module(&self.resolve, pkg), copy_path);
        }
        let mut out = format!("\n/// {doc}\npub mod {module} {{\n");
        for (ns, packages) in namespaces {
            writeln!(out, "    pub mod {ns} {{").unwrap();
            for (pkg, copy) in packages {
                writeln!(out, "        pub use {raw}::{copy} as {pkg};").unwrap();
            }
            writeln!(out, "    }}").unwrap();
        }
        out.push_str("}\n");
        out
    }
}

/// Two packages, like `a:b-c` and `a-b:c`, would share one copy package.
fn check_copies(resolve: &Resolve, prefix: &str, child: &str, ids: &[InterfaceId]) -> Result<()> {
    let mut copy_of = BTreeMap::new();
    for id in ids.iter() {
        let pkg = &resolve.packages[resolve.interfaces[*id].package.unwrap()].name;
        let copy = copy::copy_package_name(prefix, child, pkg);
        if let Some(other) = copy_of.insert(copy.clone(), pkg.clone())
            && other != *pkg
        {
            bail!("`{other}` and `{pkg}` would both be copied to `{copy}`");
        }
    }
    Ok(())
}

/// Plans and generates in one step.
pub fn generate(resolve: &Resolve, packages: &[PackageId], config: &Config) -> Result<Output> {
    Plan::new(resolve, packages, config)?.generate()
}

fn parse_patterns(patterns: &[String]) -> Result<Vec<Pattern>> {
    patterns.iter().map(|p| Pattern::parse(p)).collect()
}

fn matches_any(resolve: &Resolve, id: InterfaceId, patterns: &[Pattern], used: &mut [bool]) -> bool {
    let mut hit = false;
    for (p, used) in patterns.iter().zip(used.iter_mut()) {
        if p.matches(resolve, id) {
            *used = true;
            hit = true;
        }
    }
    hit
}

fn unused_patterns(patterns: &[Pattern], used: &[bool], option: &str, verb: &str, guest: &str) -> Result<()> {
    for (p, used) in patterns.iter().zip(used.iter()) {
        if !used {
            bail!("`{}` in `{option}` matches no interface {verb} by `{guest}`", p.as_str());
        }
    }
    Ok(())
}

/// The resources `id` mentions, directly or through its dependencies, with
/// the interfaces that own them.
fn resources_used(resolve: &Resolve, id: InterfaceId) -> Vec<(TypeId, InterfaceId)> {
    let mut live = LiveTypes::default();
    live.add_interface(resolve, id);
    live.iter()
        .filter_map(|ty| {
            let def = &resolve.types[ty];
            match (&def.kind, def.owner) {
                (TypeDefKind::Resource, TypeOwner::Interface(owner)) => Some((ty, owner)),
                _ => None,
            }
        })
        .collect()
}

fn resource_name(resolve: &Resolve, id: TypeId) -> &str {
    resolve.types[id].name.as_deref().unwrap_or("?")
}

fn dealias(resolve: &Resolve, mut id: TypeId) -> TypeId {
    while let TypeDefKind::Type(Type::Id(next)) = resolve.types[id].kind {
        id = next;
    }
    id
}

/// Whether `ty` contains a handle matching `f`.
fn type_has(resolve: &Resolve, ty: &Type, f: &dyn Fn(&Handle) -> bool) -> bool {
    let Type::Id(id) = ty else { return false };
    match &resolve.types[*id].kind {
        TypeDefKind::Handle(h) => f(h),
        TypeDefKind::Record(r) => r.fields.iter().any(|x| type_has(resolve, &x.ty, f)),
        TypeDefKind::Variant(v) => v.cases.iter().any(|c| c.ty.as_ref().is_some_and(|t| type_has(resolve, t, f))),
        TypeDefKind::Tuple(t) => t.types.iter().any(|t| type_has(resolve, t, f)),
        TypeDefKind::Option(t) | TypeDefKind::List(t) | TypeDefKind::Type(t) => type_has(resolve, t, f),
        TypeDefKind::Result(r) => {
            r.ok.as_ref().is_some_and(|t| type_has(resolve, t, f))
                || r.err.as_ref().is_some_and(|t| type_has(resolve, t, f))
        }
        _ => false,
    }
}

fn run(opts: Opts, resolve: &Resolve, world: WorldId) -> Result<String> {
    let mut resolve = resolve.clone();
    let mut files = Files::default();
    opts.build().generate(&mut resolve, world, &mut files)?;
    let mut out = String::new();
    for (_, bytes) in files.iter() {
        out.push_str(std::str::from_utf8(bytes)?);
    }
    Ok(out)
}

/// The module path wit-bindgen gives an interface (see its
/// `compute_module_path`), relative to where the bindings are generated.
fn module_path(resolve: &Resolve, id: InterfaceId, is_export: bool) -> String {
    let iface = &resolve.interfaces[id];
    let pkg = iface.package.unwrap();
    let mut path = Vec::new();
    if is_export {
        path.push("exports".to_string());
    }
    path.push(to_rust_ident(&resolve.packages[pkg].name.namespace));
    path.push(name_package_module(resolve, pkg));
    path.push(to_rust_ident(iface.name.as_ref().unwrap()));
    path.join("::")
}

/// wit-bindgen's name for a type (`guest` is reserved for traits).
fn camel(name: &str) -> String {
    match name {
        "guest" => "Guest_".to_string(),
        s => s.to_upper_camel_case(),
    }
}

/// p2 only: no async functions, streams, futures, or error contexts.
fn reject_unsupported(resolve: &Resolve, world: WorldId) -> Result<()> {
    let w = &resolve.worlds[world];
    let mut seen = BTreeSet::new();
    for (key, item) in w.imports.iter().chain(w.exports.iter()) {
        let funcs = match item {
            WorldItem::Interface { id, .. } => resolve.interfaces[*id].functions.values().collect::<Vec<_>>(),
            WorldItem::Function(f) => vec![f],
            WorldItem::Type { .. } => continue,
        };
        for f in funcs {
            let is_async = matches!(
                f.kind,
                FunctionKind::AsyncFreestanding | FunctionKind::AsyncMethod(_) | FunctionKind::AsyncStatic(_)
            );
            if is_async || !f.find_futures_and_streams(resolve).is_empty() {
                seen.insert(format!("{}: {}", resolve.name_world_key(key), f.name));
            }
        }
    }
    if !seen.is_empty() {
        bail!(
            "the guest world uses async functions, streams, or futures, which `child!` doesn't \
             support yet (component model p2 only):\n  {}",
            seen.into_iter().collect::<Vec<_>>().join("\n  ")
        );
    }
    Ok(())
}

